import { format, resolveConfig } from 'prettier';

import { collectMessageArguments } from './collectMessageArguments.ts';
import type { UiCatalog } from './parseUiCatalog.ts';

export const uiKeyTypesPath = 'src/i18n/uiKeys.ts';

export type GeneratedUiKeyTypes =
  | { readonly ok: true; readonly text: string }
  | { readonly ok: false; readonly problems: readonly string[] };

const header =
  '// Generated by `npm run i18n:types` from locales/en/ui.json. Do not edit by hand.\n';

const renderParams = (argumentTypes: ReadonlyMap<string, string>): string =>
  argumentTypes.size === 0
    ? 'undefined'
    : `{ ${[...argumentTypes]
        .sort(([a], [b]) => Number(a > b) - Number(a < b))
        .map(([name, tsType]) => `readonly ${name}: ${tsType};`)
        .join(' ')} }`;

function renderEntries(catalog: UiCatalog): GeneratedUiKeyTypes {
  const lines: string[] = [];
  const problems: string[] = [];
  for (const key of Object.keys(catalog).sort()) {
    const parsed = collectMessageArguments(catalog[key] ?? '');
    if (parsed.ok)
      lines.push(`readonly ${JSON.stringify(key)}: ${renderParams(parsed.argumentTypes)};`);
    else problems.push(...parsed.problems.map((problem) => `${key}: ${problem}`));
  }
  return problems.length === 0 ? { ok: true, text: lines.join('\n') } : { ok: false, problems };
}

export async function generateUiKeyTypes(
  catalog: UiCatalog,
  rootDir: string,
): Promise<GeneratedUiKeyTypes> {
  const entries = renderEntries(catalog);
  if (!entries.ok) return entries;
  const source = `${header}\nexport interface UiParams {\n${entries.text}\n}\n\nexport type UiKey = keyof UiParams;\n`;
  const filepath = `${rootDir}/${uiKeyTypesPath}`;
  const options = await resolveConfig(filepath);
  return { ok: true, text: await format(source, { ...options, filepath }) };
}
